using Vulgata.Tests.TestInfrastructure;
using Vulgata.Core.DomainServices;

namespace Vulgata.Tests;

public sealed class PreparedDemoPass2FlowPlannerTests
{
    [Trait("Suite", "SelfContained")]
    [SuiteFact("SelfContained")]
    public void CreateRuntimeBinding_CurrentProductSupport_DerivesConsumerOwnedCanonicalFlow()
    {
        PreparedPass2RuntimeRepositoryBinding consumer = RepositoryBinding("consumer", 2, 3, 4, 'a');
        PreparedPass2RuntimeRepositoryBinding provider = RepositoryBinding("provider", 5, 6, 7, 'b');
        PreparedPass2RuntimeMember[] members =
        [
            new(1, Id(10), Id(11), Id(12), consumer.RepositoryId, Id(13), [Id(14)]),
            new(2, Id(15), Id(16), Id(17), provider.RepositoryId, Id(18), [Id(19)]),
        ];
        PreparedPass2TraceEvidence[] traceEvidence =
        [
            new(1, Id(10), Id(11), "消费方调用", "src/Consumer.cs#L1-L2"),
            new(2, Id(15), Id(16), "提供方实现", "src/Provider.cs#L3-L4"),
        ];

        PreparedPass2RuntimeBinding binding = PreparedPass2RuntimeBinding.Create(
            "1.0",
            "demo-profile",
            "1.0.0",
            new string('1', 64),
            "rpc-1",
            Id(1),
            consumer,
            provider,
            Id(8),
            [Id(9)],
            members,
            traceEvidence);

        Assert.Equal(PreparedPass2FlowLimits.SupportedSchemaIdentity, binding.Flow.SchemaIdentity);
        Assert.NotEqual(Guid.Empty, binding.Flow.ManifestId);
        Assert.NotEqual(Guid.Empty, binding.Flow.FlowId);
        Assert.Equal(consumer.RepositoryId, binding.Flow.RepositoryId);
        Assert.Equal([consumer.RepositoryId, provider.RepositoryId], binding.SupportingRepositoryIds);
        Assert.Equal(members.Select(member => member.DocumentVersionId), binding.DocumentVersionIds);
        Assert.Matches("^[0-9a-f]{64}$", binding.SupportFingerprint);
        Assert.True(binding.IsCanonical());
        const string manifestHex =
            "56554c474154412d50524550415245442d50415353322d4d414e4946455354000100010000001f76756c676174612e70726570617265642d70617373322d666c6f772f312e3000020000000c64656d6f2d70726f66696c65000300000005312e302e300004000000201111111111111111111111111111111111111111111111111111111111111111";
        const string flowHex =
            "";
        const string supportHex =
            "";
        Assert.Equal(manifestHex, Convert.ToHexStringLower(binding.ManifestEnvelope.Span));
        Assert.Equal(flowHex, Convert.ToHexStringLower(binding.FlowEnvelope.Span));
        Assert.Equal(supportHex, Convert.ToHexStringLower(binding.SupportEnvelope.Span));
        Assert.Equal(Guid.Parse("de1ed1de-d2ee-894d-9707-5f5194dc6a39"), binding.Flow.ManifestId);
        Assert.Equal(Guid.Parse("1f72c739-e24c-855b-b6d7-74f1973dd13f"), binding.Flow.FlowId);
        Assert.Equal(
            "029ae5559c36a9c9fdd5a2484d921773fbb23d2c914d525a35d795cf7e7ebdb5",
            binding.SupportFingerprint);
    }

    private static PreparedPass2RuntimeRepositoryBinding RepositoryBinding(
        string alias,
        int repository,
        int scanRun,
        int scanExecution,
        char commit) =>
        new(
            alias,
            $"git-{alias}",
            Id(repository),
            Id(scanRun),
            Id(scanExecution),
            $"refs/tags/{alias}",
            new string(commit, 40),
            new string(commit, 40));

    private static Guid Id(int value) =>
        Guid.Parse($"00000000-0000-0000-0000-{value:D12}");
}
